<?php $filters=array_intersect_key($_GET,array_flip(['department','programme','academic_year','study_year','semester','section','kind']));$cohortSelected=!empty($filters['programme'])&&!empty($filters['academic_year'])&&!empty($filters['study_year'])&&!empty($filters['semester']);$submitted=acReportRecords($user,$filters+['_summary_only'=>!$cohortSelected]);?>
<section class="card"><h2>Submitted academic records</h2><p class="notice">Select programme, academic year, year and semester to load student reports or export Excel. The module list below is available across departments.</p><p><?= $user['role']==='pl'?'Your department only.':'All departments.'?> Draft student data is private to its tutor. Admin has access across departments, including student entries and corrections. PL reviews department marks; Exam Cell, DAA and Admin can download consolidated marks across departments.</p><form method="get" class="ac-report-filter"><input type="hidden" name="page" value="ac_reports"><div class="form-grid"><?php acField('department','Department',$filters,$user['role']==='pl'?[$user['department']]:departments(),'text',false);acField('programme','Programme',$filters,examProgrammes(),'text',false);acField('academic_year','Academic year',$filters,[],'text',false);acField('study_year','Year',$filters,['I','II','III','IV'],'text',false);acField('semester','Semester',$filters,['I','II'],'text',false);acField('section','Section (normally A)',$filters,[],'text',false);acField('kind','Record type',$filters,saReviewer($user)?acKinds():array_diff_key(acKinds(),['attendance'=>true]),'text',false);?></div><div class="ac-toolbar"><button>View reports</button><?php if($cohortSelected):?><a class="button secondary" href="?<?=e(http_build_query(array_merge($filters,['page'=>'ac_download','mode'=>'report'])))?>">Download Excel report</a><?php endif;?><a href="?page=ac_reports">Clear filters</a></div></form></section>
<?php $studentCount=[];foreach($submitted as $r)foreach($r['entries']as $v)$studentCount[$r['programme'].'|'.$r['academic_year'].'|'.$v['student_id']]=true;?><div class="stats"><div><small>Submitted records</small><strong><?=count($submitted)?></strong></div><div><small>Students in this selection</small><strong><?=$cohortSelected?count($studentCount):'—'?></strong></div><div><small>Attendance records</small><strong><?=count(array_filter($submitted,fn($r)=>$r['kind']==='attendance'))?></strong></div><div><small>Assessment records</small><strong><?=count(array_filter($submitted,fn($r)=>$r['kind']==='assessment'))?></strong></div></div>
<section class="card"><h2>Module submissions</h2><div class="table-wrap"><table class="ac-bordered"><thead><tr><th>Receipt / module</th><th>Programme / cohort</th><th>Tutor</th><th>Type</th><th>DPD hours</th><th>Submitted</th><th></th></tr></thead><tbody><?php $pn=max(1,(int)($_GET['p']??1));$pages=max(1,(int)ceil(count($submitted)/10));$pn=min($pages,$pn);foreach(array_slice($submitted,($pn-1)*10,10)as $r):?><tr><td>#<?=$r['id']?> · <?=e($r['module_code'])?><small><?=e($r['module_name'])?></small></td><td><?=e($r['programme'])?><small><?=e($r['academic_year'].' · Year '.$r['study_year'].' · Sem '.$r['semester'].' · '.$r['section'])?></small></td><td><?=e($r['tutor_name'])?></td><td><?=e(acKinds()[$r['kind']])?></td><td><?=e($r['contact_hours'])?></td><td><?=e($r['submitted_at'])?></td><td><a href="?page=ac_record&id=<?=$r['id']?>">View →</a></td></tr><?php endforeach;if(!$submitted):?><tr><td colspan="7">No submitted records match these filters.</td></tr><?php endif;?></tbody></table></div><div class="pagination">Page <?=$pn?> of <?=$pages?><div><?php if($pn>1):?><a href="?<?=e(http_build_query(array_merge($_GET,['p'=>$pn-1])))?>">Previous</a><?php endif;if($pn<$pages):?><a href="?<?=e(http_build_query(array_merge($_GET,['p'=>$pn+1])))?>">Next</a><?php endif;?></div></div></section>
<?php $short=[];foreach($submitted as $record)if($record['kind']==='attendance'){$a=acAttendance($record);foreach($a['students']as $s)if($s['recorded_percentage']<90)$short[]=[$record,$s,$a['complete']];}if($short):?><section class="card"><h2>Attendance review list (<?=count($short)?>)</h2><p>Below 80%: not allowed to sit the exam. 80% to below 90%: supporting document and verification required. At least 90%: allowed. Eligibility uses recorded sessions, including extra classes; DPD coverage is for reference.</p><div class="table-wrap"><table class="ac-bordered"><thead><tr><th>Student / ID</th><th>Programme / module</th><th>Recorded-session %</th><th>DPD hours</th><th>Remarks</th></tr></thead><tbody><?php foreach($short as [$record,$s,$complete]):?><tr class="<?=$s['recorded_percentage']<80?'ac-shortage':''?>"><td><?=e($s['name'])?><small><?=e($s['id'])?></small></td><td><?=e($record['programme'])?><small><?=e($record['module_code'].' · '.$record['academic_year'])?></small></td><td><?=e($s['recorded_percentage'])?>%<small><?=$s['present']?> present / <?=e($s['recorded'])?> recorded sessions</small></td><td><?=e($record['contact_hours'])?></td><td><?=e(saEligibility($record,$s))?><?=!$complete?'<small>Provisional coverage</small>':''?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php foreach(acConsolidate($submitted)as $label=>$g):?><section class="card"><div class="ac-toolbar"><h2>Consolidated marks</h2><a class="button" href="?<?=e(http_build_query(array_merge($filters,['page'=>'ac_download','mode'=>'report','kind'=>'assessment'])))?>">Download consolidated marks (Excel)</a></div><p><b><?=e($label)?></b></p><p class="notice">Average covers these <?=count($g['modules'])?> submitted modules only. It is not a final programme result: missing modules cannot be identified without an expected module list. All modules currently have equal weight. The latest submitted re-assessment updates the affected module total (successful result capped at 50). Original marks remain in the module record.</p><div class="table-wrap"><table class="ac-bordered ac-consolidated"><thead><tr><th rowspan="2">Student name</th><th rowspan="2">Student ID</th><?php foreach($g['modules']as $r):?><th colspan="4"><?=e($r['module_code'])?></th><?php endforeach;?><th rowspan="2">Available-module average</th></tr><tr><?php foreach($g['modules']as $r):?><th>CA</th><th>ESE</th><th>Total</th><th>Result</th><?php endforeach;?></tr></thead><tbody><?php foreach($g['students']as $s):?><tr><td><?=e($s['name'])?><?=$s['name_conflict']?'<small class="error">Check name mismatch across modules</small>':''?></td><td><?=e($s['id'])?></td><?php foreach($g['modules']as $id=>$r):$m=$s['marks'][$id]??null;?><td><?=e($m['ca']??'—')?></td><td><?=e($m?($m['ese']??'N/A'):'—')?></td><td><?=e($m['total']??'Missing')?><?=isset($m['reassessment_id'])?'<small>RA #'.(int)$m['reassessment_id'].'</small>':''?></td><td><?=e($m['result']??'Incomplete')?></td><?php endforeach;?><td><b><?=e($s['average']===null?'Incomplete':$s['average'].'%')?></b><?php $eligibility=acEligibility(reset($g['modules']),$s['id']);?><small>Original outcome: <?=e($eligibility['message'])?></small><?php if(in_array('Fail',array_column($s['marks'],'result'),true)):?><small>One or more module results: Fail</small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?>
